########## useContentful.ts ##########
import { useState, useEffect } from 'react';
import { getContentfulConfig } from '../config/contentful';
import type { ContentfulAsset } from '../types/contentful';

type ContentfulLink = {
  sys: {
    type: 'Link';
    linkType: 'Asset' | 'Entry';
    id: string;
  };
};

type ContentfulRawEntry = {
  fields: Record<string, ContentfulLink | ContentfulAsset | unknown>;
  [key: string]: unknown;
};

type ContentfulEntriesResponse = {
  items: ContentfulRawEntry[];
  includes?: {
    Asset?: ContentfulAsset[];
  };
};

export const useContentfulEntry = <T>(entryId: string, preview = false) => {
  const [data, setData] = useState<T | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    const controller = new AbortController();

    const fetchEntry = async () => {
      const config = getContentfulConfig();
      if (!config.spaceId || !config.accessToken) {
        setError(new Error('Contentful configuration missing'));
        setIsLoading(false);
        return;
      }

      try {
        const { spaceId, accessToken, previewAccessToken, environment } = config;
        const baseUrl = preview ? 'https://preview.contentful.com' : 'https://cdn.contentful.com';
        const token = preview ? previewAccessToken : accessToken;

        // Use the search endpoint with sys.id so include=2 resolves linked assets
        const url = `${baseUrl}/spaces/${spaceId}/environments/${environment}/entries?sys.id=${entryId}&access_token=${token}&include=2`;

        const response = await fetch(url, { signal: controller.signal });

        if (!response.ok) {
          throw new Error(`Contentful API error: ${response.status}`);
        }

        const result: ContentfulEntriesResponse = await response.json();

        // Resolve linked assets into the entry fields
        const item = result.items[0];
        if (!item) {
          throw new Error(`Entry ${entryId} not found`);
        }
        const resolvedItem = { ...item };
        if (item.fields) {
          Object.keys(item.fields).forEach((fieldKey) => {
            const fieldValue = item.fields[fieldKey] as ContentfulLink;
            if (fieldValue?.sys?.type === 'Link' && fieldValue?.sys?.linkType === 'Asset') {
              const linked = result.includes?.Asset?.find((asset) => asset.sys.id === fieldValue.sys.id);
              if (linked) resolvedItem.fields[fieldKey] = linked;
            }
          });
        }
        setData(resolvedItem as T);
      } catch (err) {
        if (err instanceof DOMException && err.name === 'AbortError') return;
        setError(err instanceof Error ? err : new Error('Unknown error'));
      } finally {
        setIsLoading(false);
      }
    };

    void fetchEntry();
    return () => controller.abort();
  }, [entryId, preview]);

  return { data, isLoading, error };
};

export const useContentfulEntries = <T>(contentType: string, preview = false) => {
  const [data, setData] = useState<T[] | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    const controller = new AbortController();

    const fetchEntries = async () => {
      const config = getContentfulConfig();
      if (!config.spaceId || !config.accessToken) {
        setError(new Error('Contentful configuration missing'));
        setIsLoading(false);
        return;
      }

      try {
        const { spaceId, accessToken, previewAccessToken, environment } = config;
        const baseUrl = preview ? 'https://preview.contentful.com' : 'https://cdn.contentful.com';
        const token = preview ? previewAccessToken : accessToken;

        // Include assets in the response
        const url = `${baseUrl}/spaces/${spaceId}/environments/${environment}/entries?content_type=${contentType}&access_token=${token}&include=2`;

        const response = await fetch(url, { signal: controller.signal });

        if (!response.ok) {
          const errorText = await response.text();
          console.error('Contentful API error response:', errorText);
          throw new Error(`Contentful API error: ${response.status}`);
        }

        const result: ContentfulEntriesResponse = await response.json();

        // Resolve linked assets
        const resolvedItems = result.items.map((item) => {
          const resolvedItem = { ...item };

          if (item.fields) {
            Object.keys(item.fields).forEach((fieldKey) => {
              const fieldValue = item.fields[fieldKey] as ContentfulLink;
              if (fieldValue?.sys?.type === 'Link' && fieldValue?.sys?.linkType === 'Asset') {
                const assetId = fieldValue.sys.id;
                const linkedAsset = result.includes?.Asset?.find((asset) => asset.sys.id === assetId);
                if (linkedAsset) {
                  resolvedItem.fields[fieldKey] = linkedAsset;
                }
              }
            });
          }

          return resolvedItem;
        });

        setData(resolvedItems as T[]);
      } catch (err) {
        if (err instanceof DOMException && err.name === 'AbortError') return;
        console.error('Contentful fetch error:', err);
        setError(err instanceof Error ? err : new Error('Unknown error'));
      } finally {
        setIsLoading(false);
      }
    };

    void fetchEntries();
    return () => controller.abort();
  }, [contentType, preview]);

  return { data, isLoading, error };
};

