import React from 'react';
import { Box, Image, Text, Skeleton } from '@salesforce/retail-react-app/app/components/shared/ui';
import { ContentfulLivePreview } from '@contentful/live-preview';
import { useProduct } from '@salesforce/commerce-sdk-react';
import { proxyImageUrl } from '../../utils/sfccImage';

type ProductHeroProps = {
  productHero: string;
  entryId?: string;
  locale?: string;
};

export const ProductHero = ({ productHero, entryId, locale = 'en-US' }: ProductHeroProps) => {
  const inspectorProps = entryId ? ContentfulLivePreview.getProps({ entryId, fieldId: 'productHero', locale }) : {};

  const { data: product, isLoading } = useProduct(
    { parameters: { id: productHero, allImages: true } },
    { enabled: !!productHero },
  );

  const heroImage = product?.imageGroups?.find((g) => g.viewType === 'large')?.images?.[0];
  const description = product?.shortDescription ?? product?.longDescription;

  return (
    <Box
      padding={8}
      maxWidth="container.xl"
      marginX="auto"
      display="flex"
      flexDirection={{ base: 'column', md: 'row' }}
      alignItems="center"
      gap={8}
      {...inspectorProps}
    >
      <Skeleton isLoaded={!isLoading} flexShrink={0}>
        {heroImage ? (
          <Image
            src={proxyImageUrl(heroImage.disBaseLink ?? heroImage.link ?? '')}
            alt={heroImage.alt ?? product?.name ?? ''}
            boxSize={{ base: '240px', md: '320px' }}
            objectFit="cover"
            borderRadius="md"
            loading="lazy"
          />
        ) : (
          <Box boxSize={{ base: '240px', md: '320px' }} bg="gray.100" borderRadius="md" />
        )}
      </Skeleton>
      <Box>
        <Skeleton isLoaded={!isLoading} mb={3}>
          <Text fontSize="2xl" fontWeight="bold">
            {product?.name ?? productHero}
          </Text>
        </Skeleton>
        {description && (
          <Skeleton isLoaded={!isLoading}>
            <Text color="gray.600" fontSize="md">
              {description}
            </Text>
          </Skeleton>
        )}
      </Box>
    </Box>
  );
};

