import React from 'react';
import { Box, Image, Link, Skeleton, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
import { useProduct } from '@salesforce/commerce-sdk-react';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import { proxyImageUrl } from '../../../utils/sfccImage';

type HotspotPopupProps = {
  productId: string;
};

const HotspotPopup = ({ productId }: HotspotPopupProps) => {
  const { data: product, isLoading } = useProduct(
    { parameters: { id: productId, allImages: true } },
    { enabled: !!productId },
  );

  if (!isLoading && !product) return null;

  const image = product?.imageGroups?.find((g) => g.viewType === 'small')?.images?.[0];
  const price = product?.price;

  return (
    <Box w="180px">
      <Skeleton isLoaded={!isLoading}>
        {image && (
          <Image
            src={proxyImageUrl(image.disBaseLink ?? image.link ?? '')}
            alt={image.alt ?? product?.name ?? ''}
            w="100%"
            h="120px"
            objectFit="cover"
            loading="lazy"
            mb={2}
          />
        )}
      </Skeleton>
      <Skeleton isLoaded={!isLoading} mb={1}>
        <Text fontSize="sm" fontWeight="medium" noOfLines={2}>
          {product?.name ?? ''}
        </Text>
      </Skeleton>
      {price != null && (
        <Skeleton isLoaded={!isLoading} mb={2}>
          <Text fontSize="sm" color="gray.600">
            ${price.toFixed(2)}
          </Text>
        </Skeleton>
      )}
      <Skeleton isLoaded={!isLoading}>
        <Link
          href={productUrlBuilder({ id: productId })}
          fontSize="xs"
          fontWeight="semibold"
          textDecoration="underline"
          display="block"
        >
          Shop Now
        </Link>
      </Skeleton>
    </Box>
  );
};

export default HotspotPopup;

