/**
 * Contentful Configuration
 *
 * Values are sourced from config/default.js via getConfig(), which is evaluated
 * server-side (where process.env is available) and serialized into the bundle.
 * This means the delivery token is available client-side (it's public/read-only),
 * while the preview token is only populated when CONTENTFUL_PREVIEW_TOKEN is set
 * in the server environment.
 */
import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';

type ContentfulConfig = {
  spaceId: string;
  accessToken: string;
  environment: string;
  previewAccessToken: string;
};

export const getContentfulConfig = (): ContentfulConfig => {
  const { app } = getConfig();
  return (app as { contentful: ContentfulConfig }).contentful;
};
