const renderRichText = (richText: ContentfulRichText): React.ReactNode => {
  if (!richText.content || richText.content.length === 0) {
    return null;
  }

  return richText.content.map((node, index) => {
    if (node.nodeType === 'text' && node.value) {
      const text = node.value;
      if (node.marks && node.marks.length > 0) {
        const markTypes = node.marks.map((mark) => mark.type);
        if (markTypes.includes('bold')) {
          return <strong key={index}>{text}</strong>;
        }
        if (markTypes.includes('italic')) {
          return <em key={index}>{text}</em>;
        }
      }
